// These are all 25 upstream vectors, not expected values generated by this
// implementation. See testdata/README.md for their source and license.
func TestERISOfficialVectors(t *testing.T) {
	file, err := os.Open("testdata/eris-test-vectors-v1.0.0.tar.gz")
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = file.Close() }()
	compressed, err := gzip.NewReader(file)
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = compressed.Close() }()
	archive := tar.NewReader(compressed)
	decode := func(value string) []byte {
		t.Helper()
		data, err := base32.StdEncoding.WithPadding(base32.NoPadding).DecodeString(value)
		if err != nil {
			t.Fatal(err)
		}
		return data
	}
	positive, negative := 0, 0
	for {
		header, err := archive.Next()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			t.Fatal(err)
		}
		if !strings.HasSuffix(header.Name, ".json") {
			continue
		}
		var vector struct {
			Type    string
			Content string
			Secret  string `json:"convergence-secret"`
			Size    int    `json:"block-size"`
			URN     string
			Blocks  map[string]string
		}
		if err := json.NewDecoder(archive).Decode(&vector); err != nil {
			t.Fatal(err)
		}
		blocks := make(eris.BlockSet)
		for ref, data := range vector.Blocks {
			reference, err := eris.ParseReference(ref)
			if err != nil {
				t.Fatal(err)
			}
			blocks[reference] = decode(data)
		}
		capability, err := eris.ParseURN(vector.URN)
		if err != nil {
			t.Fatal(err)
		}
		switch vector.Type {
		case "positive":
			positive++
		case "negative":
			negative++
		default:
			t.Fatalf("unknown vector type %q", vector.Type)
		}
		t.Run(path.Base(header.Name), func(t *testing.T) {
			content := decode(vector.Content)
			decoded, err := eris.Decode(capability, blocks)
			reader, readErr := erisreader.NewReader(capability, blocks)
			var streamed []byte
			if readErr == nil {
				streamed, readErr = io.ReadAll(reader)
				_ = reader.Close()
			}
			if vector.Type == "negative" {
				if err == nil || readErr == nil {
					t.Fatalf("invalid vector accepted: Decode=%v, Reader=%v", err, readErr)
				}
				return
			}
			if err != nil || readErr != nil || !bytes.Equal(decoded, content) || !bytes.Equal(streamed, content) {
				t.Fatalf("decode mismatch: Decode=%v, Reader=%v", err, readErr)
			}
			secretBytes := decode(vector.Secret)
			if len(secretBytes) != len(eris.Secret{}) {
				t.Fatal("invalid vector secret")
			}
			secret := eris.Secret(secretBytes)
			actualCap, actualBlocks, err := eris.Encode(content, secret, eris.BlockSize(vector.Size))
			if err != nil || actualCap != capability || !reflect.DeepEqual(actualBlocks, blocks) {
				t.Fatalf("Encode differs from official capability or blocks: %v", err)
			}
			for _, chunk := range []int{37, 32768} {
				actualBlocks = make(eris.BlockSet)
				actualCap, err = EncodeContent(smallChunkReader{bytes.NewReader(content), chunk}, secret, eris.BlockSize(vector.Size), actualBlocks)
				if err != nil || actualCap != capability || !reflect.DeepEqual(actualBlocks, blocks) {
					t.Fatalf("EncodeContent chunk %d differs from official capability or blocks: %v", chunk, err)
				}
			}
		})
	}
	if positive != 13 || negative != 12 {
		t.Fatalf("incomplete vector set: %d positive, %d negative", positive, negative)
	}
}

// This fixture is hand-written from the v2 CDDL and RFC 8949 section 4.2.1.
// It distinguishes bytewise ordering from length-first and native path order.
func TestV2CanonicalMapVector(t *testing.T) {
	capability := eris.Capability{BlockSize: eris.BlockSize1KiB}
	entries := []Entry{
		{Path: []string{"z"}, Capability: capability, Size: 23},
		{Path: []string{"aa"}, Type: Executable, Capability: capability, Size: 24},
		{Path: []string{"é"}, Type: Symlink, Target: "/a//b/"},
		{Path: []string{"aaa"}, Capability: capability, Size: 256, Compression: Lzip},
		{Path: []string{"long-name"}, Type: Subdirectory, Capability: capability},
		{Path: []string{"a", "b"}, Type: Symlink, Target: "../c"},
		{Path: []string{"a", "z"}, Type: Symlink, Target: ""},
	}
	capHex := "d9011458420a00" + strings.Repeat("00", 64)
	wire := "da657269748202a7" +
		"81617a8300" + capHex + "17" +
		"816261618301" + capHex + "1818" +
		"8162c3a982028560616160616260" +
		"81636161618300" + capHex + "da4c5a4950190100" +
		"81696c6f6e672d6e616d658203" + capHex +
		"8261616162820282622e2e6163" +
		"826161617a82028160"
	want, err := hex.DecodeString(wire)
	if err != nil {
		t.Fatal(err)
	}
	for range len(entries) {
		for range 2 {
			got, err := (Index{Entries: entries}).MarshalBinary()
			if err != nil || !bytes.Equal(got, want) {
				t.Fatalf("canonical map bytes: %x, %v; want %x", got, err, want)
			}
			slices.Reverse(entries)
		}
		entries = append(entries[1:], entries[0])
	}
	parsed, err := ParseIndex(want)
	if err != nil {
		t.Fatal(err)
	}
	encoded, err := parsed.MarshalBinary()
	if err != nil || !bytes.Equal(encoded, want) {
		t.Fatalf("canonical map round trip: %v", err)
	}
	empty, err := (Index{}).MarshalBinary()
	if err != nil || hex.EncodeToString(empty) != "da657269748202a0" {
		t.Fatalf("empty v2 index: %x, %v", empty, err)
	}
}

func TestIndexRecommendedBlockSizeBoundary(t *testing.T) {
	for _, size := range []int{16383, 16384, 16385} {
		index := Index{Entries: []Entry{{Path: []string{"f"}, Type: Symlink, Target: strings.Repeat("a", size-17)}}}
		wire, err := index.MarshalBinary()
		if err != nil || len(wire) != size {
			t.Fatalf("index length: %d, %v; want %d", len(wire), err, size)
		}
		blockSize := eris.BlockSize1KiB
		if size >= 16384 {
			blockSize = eris.BlockSize32KiB
		}
		want, wantBlocks, err := eris.Encode(wire, eris.Secret{}, blockSize)
		if err != nil {
			t.Fatal(err)
		}
		blocks := make(eris.BlockSet)
		got, err := EncodeIndex(index, eris.Secret{}, blocks)
		if err != nil || got != want || !reflect.DeepEqual(blocks, wantBlocks) {
			t.Fatalf("index size %d: wrong capability or blocks: %v", size, err)
		}
	}
}
